        theta00=theta0+per_ic*rndn(rows(theta0),1);
        {theta1,fmin,g,retcode}=optmum(&reg,theta00) ; 
        j=t*fmin;

        x=x|(j~retcode~theta1');

    i2=i2+1; endo;

    x=sortc(x,1);
    j=x[1,1]; 
    retcode=x[1,2];
    theta1=x[1,3:cols(x)]';

@
    "--------------";
    "iteration" i ;
    "j, retcode and theta1'"; x[1,.];
@


    if (n_iter>1)*(i==n_iter);

        d=gradp(&reg_hm,theta1);
        avar=invpd(d'w*d);

        "--------------";
        "betas and mu estimates; standard error below"; theta1' ; sqrt(diag(avar)/t)';
        "j statistic, p-value, and optmum retcode" ; j~cdfchic(j,df)~retcode ;
        "--------------";

    endif;

    s= newe(reg_h(theta1),lag_nw);
    w=invpd( s ) ; 
    theta0=theta1;

    if n_iter==1;

        x={};

        i2=1; do while i2<=n_ic;

            theta00=theta0+per_ic*rndn(rows(theta0),1);
            {theta1,fmin,g,retcode}=optmum(&reg_cu,theta00) ;  
            j=t*fmin ;

            x=x|(j~retcode~theta1');

        i2=i2+1; endo;

        x=sortc(x,1);
        j=x[1,1]; 
        retcode=x[1,2];
        theta1=x[1,3:cols(x)]';

        d=gradp(&reg_hm,theta1);
        s=newe(reg_h(theta1),lag_nw);
        si=invpd(s);

        ds=d-0.5*(reg_hm(theta1)'si.*.eye(rows(d)))*gradp(&reg_s,theta1);
        avar=inv(ds'si*ds);

        "---------------";
        "betas and mu estimates; standard error below"; theta1' ; sqrt(diag(avar)/t)';
        "j statistic, p-value, and optmum retcode" ; j~cdfchic(j,df)~retcode ;
        "---------------";

    endif;

i=i+1; endo;


@--------------------------------------------------------proc-----------------------------------------------------------------------@


proc  newe ( h , q ) ;

	local  u, t,  i , s, c ;

	t=rows(h) ;

    u=h-(cen_nw.==1)* meanc(h)' ;
	s=u'u / t ;  

	i=1 ; do while i<=q ; 
		c=u[i+1:t,.]'u[1:t-i,.]  / t  ; 
		s=s+ (1-(i/(q+1))) *  (  c+c' ) ; 
	i=i+1 ; endo ; 

	retp( s ) ;
endp; 

@--------------------------------@

proc  sdf_hp ( theta ) ;

	local   h_r_t, h_f_t ;

    h_r_t= r.*(sin(theta)+f*cos(theta)) ; 
    h_f_t= f.*(sin(theta)+f*cos(theta)) ;

	   retp( h_r_t~h_f_t  ) ;
endp; 

proc  sdf_h2p ( theta ) ;

    local   ups, mu, u ,  h_r_t, h_f_t , h_u_t  ;

    ups=theta[1];
    mu=theta[2];

    u=f-mu';
    h_r_t= r.*(sin(ups)+u*cos(ups)) ; 
    h_f_t= f.*(sin(ups)+u*cos(ups)) ;
    h_u_t= u ;

  	   retp(h_r_t~h_f_t~h_u_t );
endp; 


proc  sdf_h ( theta ) ;

	local  h_r_t, h_f_t ;

    h_r_t= r.*(1-f*theta) ; 
    h_f_t= f.*(1-f*theta) ;

	   retp( h_r_t~h_f_t  ) ;
endp; 


proc  sdf_h2 ( theta ) ;

	local  tau, mu, 
            u, h_r_t, h_f_t, h_u_t ;

    tau=theta[1:k];
    mu=theta[k+1:2*k];

    u=f-mu';
    h_r_t= r.*(1-u*tau) ; 
    h_f_t= f.*(1-u*tau) ;
    h_u_t= u ;

  	   retp(h_r_t~h_f_t~h_u_t );
endp; 


proc  reg_h ( theta ) ;

	local   beta, mu, bb   ;

    beta=theta[1:k*n];
    mu=theta[k*n+1:k*n+k];

    bb=reshape(beta,k,n)';

	retp( ((ones(t,1)~f) *~ (r-f*bb')) ~ (f-mu') ) ;

endp; 




@--------------------------------@

proc  sdfp ( theta ) ;

	local  h  ;

    h=meanc(sdf_hp(theta)) ; 

	retp( h'w*h  ) ;

endp; 


proc  sdf2p ( theta ) ;

	local  h  ;

    h=meanc(sdf_h2p(theta)) ; 

	retp( h'w*h  ) ;
endp; 



proc  sdf ( theta ) ;

	local  h  ;

    h=meanc(sdf_h(theta)) ; 

	retp( h'w*h  ) ;

endp; 


proc  sdf2 ( theta ) ;

	local  h  ;

    h=meanc(sdf_h2(theta)) ; 

	retp( h'w*h  ) ;
endp; 



proc  reg ( theta ) ;

	local    h ;

    h= meanc(reg_h(theta)) ; 

	retp( h'w*h ) ;

endp; 



@--------------------------------@

proc  sdf_hmp ( theta ) ;

	retp( meanc(sdf_hp(theta))  ) ;

endp; 

proc  sdf_sp ( theta ) ;

	retp( vec(newe(sdf_hp(theta),lag_nw))  ) ;

endp; 


proc  sdf_hm2p ( theta ) ;

	retp( meanc(sdf_h2p(theta))  ) ;
endp; 

proc  sdf_s2p ( theta ) ;

	retp( vec(newe(sdf_h2p(theta),lag_nw))  ) ;

endp; 



proc  sdf_hm ( theta ) ;

	retp( meanc(sdf_h(theta))  ) ;

endp; 

proc  sdf_s ( theta ) ;

	retp( vec(newe(sdf_h(theta),lag_nw))  ) ;

endp; 


proc  sdf_hm2 ( theta ) ;

	retp( meanc(sdf_h2(theta))  ) ;
endp; 

proc  sdf_s2 ( theta ) ;

	retp( vec(newe(sdf_h2(theta),lag_nw))  ) ;

endp; 



proc  reg_hm ( theta ) ;

	retp( meanc(reg_h(theta)) ) ;

endp; 

proc  reg_s ( theta ) ;

	retp( vec(newe(reg_h(theta),lag_nw))  ) ;

endp; 



@--------------------------------@

proc  sdf_cup ( theta ) ;

	local  h_t  ;

    h_t=sdf_hp(theta) ; 

	retp( ols_r2(h_t)  ) ;
endp; 


proc  sdf_cu2p ( theta ) ;

	local  h_t  ;

    h_t=sdf_h2p(theta) ; 

	retp( ols_r2(h_t)  ) ;
endp; 



proc  sdf_cu ( theta ) ;

	local  h_t  ;

    h_t=sdf_h(theta) ; 

	retp( ols_r2(h_t)  ) ;
endp; 


proc  sdf_cu2 ( theta ) ;

	local  h_t  ;

    h_t=sdf_h2(theta) ; 

	retp( ols_r2(h_t)  ) ;
endp; 



proc  reg_cu ( theta ) ;

	local    h_t ;

    h_t= reg_h(theta) ; 

	retp( ols_r2(h_t) ) ;

endp; 



proc  ols_r2 ( mom ) ;

    local  alpha1,res1,pre1, c,fu,  alpha2,res2,pre2, kma,b ;

        { alpha1,res1,pre1 } = OLSQR2(nw_sri'ones(t,1),nw_sr*mom)   ;

        c=pre1'pre1/(t^2) ;

        fu=c;

        if cen_nw==1 ;

            { alpha2,res2,pre2 } = OLSQR2(nw_sr*ones(t,1),nw_sr*mom)   ;

            kma=res2'res2 ;
            b=-pre1'pre2/t  ;

            fu=c/(kma*c+(1+b)^2) ;

        endif;

    retp( fu ) ;

endp; 



